import type { Band, DimensionKey, Pattern } from "@/lib/scoring";
import type { Locale } from "@/lib/i18n/config";

export type Answers = Record<string, string | number>;

/** A dimension score as stored/displayed. */
export interface ResultDimension {
  key: DimensionKey;
  label: string;
  score: number; // 0–100
}

/** The paid long-form narrative, generated by the AI after payment and cached. */
export interface NarrativeStep {
  title: string;
  detail: string;
}
export interface NarrativeDimensionNote {
  key: DimensionKey;
  note: string;
}
export interface Narrative {
  summary: string;
  dimensionNotes: NarrativeDimensionNote[];
  riskDetail: string;
  recommendations: NarrativeStep[];
}

/**
 * The full result stored in KV. Everything except `narrative` is computed
 * deterministically (plus one short AI headline). `narrative` is the paid
 * content, added lazily after payment.
 */
export interface StoredResult {
  healthScore: number; // 0–100
  band: Band;
  pattern: Pattern;
  patternSlug: string;
  dimensions: ResultDimension[];
  strength: ResultDimension; // biggest strength
  risk: ResultDimension; // biggest risk
  headline: string; // short AI line (free)
  safetyFlag: boolean;
  createdAt: number;
  locale?: Locale; // language the result was produced in (default "en")
  narrative?: Narrative; // paid-only
}

/** What an unpaid viewer may see: everything except the paid narrative. */
export type FreeResult = Omit<StoredResult, "narrative">;

/** Strip the paid narrative from a stored result. */
export function toFreeResult(full: StoredResult): FreeResult {
  const { narrative, ...free } = full;
  void narrative;
  return free;
}

/** Response shape returned by /api/analyze and GET /api/result/[id]. */
export interface ResultResponse {
  resultId: string;
  paid: boolean;
  result: FreeResult | StoredResult;
}
